  function configure(mode,parts){if(session.starting){status('Espera a que termine de preparar la reproducción.');$('#ksUnit').value=session.mode;return;}pause();let replacement;try{replacement=LQTACKaraokeSyncModel.flatten(blocks,order,{mode,parts});}catch(e){status(e.message);$('#ksUnit').value=session.mode;return;}if(session.cursor&&!confirm('Cambiar la unidad o la separación reinicia las marcas de esta sesión. Lo aplicado al proyecto no cambia hasta Aplicar. ¿Continuar?')){$('#ksUnit').value=session.mode;return;}session.mode=mode;session.parts=structuredClone(parts);session.partsDirty=false;session.entries=entries=replacement;session.cursor=0;session.marks=[];timelineTime=0;void renderTimelineAt(0);showUnits();refresh();status('Preparado para marcar por '+plural()+'. Los cambios se guardan al Aplicar.');}
