  const limit=Math.max(.1,...timelineClips().map(c=>{const t=clipTiming(c);return t.startSeconds+t.durationSeconds;}));$('#ksSeek').max=limit;$('#ksSeek').value=Math.min(limit,Math.max(0,timelineTime));
